/**
 * Generate HowTo structured data for a genre gear guide (Issue #4574).
 * Steps are derived from the guide's own "what to look for" checklist and
 * its top pro/budget picks — no invented content.
 * @param {Object} guide - A GENRE_GEAR_GUIDES entry
 */
export function generateGenreGuideHowToSchema(guide) {
  if (!guide) return null;

  const steps = [];

  (guide.whatToLookFor?.features || []).forEach((feature) => {
    steps.push({
      '@type': 'HowToStep',
      name: `Consider ${feature.name}`,
      text: feature.description,
      position: steps.length + 1,
    });
  });

  const topPick = guide.proRecommendations?.pedals?.[0];
  if (topPick) {
    steps.push({
      '@type': 'HowToStep',
      name: `Choose a top pick: ${topPick.name}`,
      text: topPick.verdict || topPick.description,
      position: steps.length + 1,
    });
  }

  const budgetPick = guide.budgetOptions?.pedals?.[0];
  if (budgetPick) {
    steps.push({
      '@type': 'HowToStep',
      name: `Or go budget with: ${budgetPick.name}`,
      text: budgetPick.verdict || budgetPick.description,
      position: steps.length + 1,
    });
  }

  if (!steps.length) return null;

  return {
    '@context': 'https://schema.org',
    '@type': 'HowTo',
    name: guide.title,
    description: guide.description,
    image: guide.ogImage ? `https://metalforge.io${guide.ogImage}` : undefined,
    totalTime: guide.readingTime ? `PT${guide.readingTime.replace(' min', 'M')}` : undefined,
    datePublished: guide.datePublished,
    dateModified: guide.dateModified,
    step: steps,
  };
}

export default GENRE_GEAR_GUIDES;
